// (or just `npm run dev` / `npm run build`, which do it automatically).

importScripts('https://www.gstatic.com/firebasejs/10.13.1/firebase-app-compat.js');
importScripts('https://www.gstatic.com/firebasejs/10.13.1/firebase-messaging-compat.js');

firebase.initializeApp({
  "apiKey": "AIzaSyAYlk96J0ruTjEjzxDWNtjg562yt6QKH10",
  "authDomain": "kojlux-study-hub.firebaseapp.com",
  "projectId": "kojlux-study-hub",
  "storageBucket": "kojlux-study-hub.firebasestorage.app",
  "messagingSenderId": "960240769488",
  "appId": "1:960240769488:web:309df71ebf8166a85881d5"
});

const messaging = firebase.messaging();

// Fires when a push arrives while no tab has the app open/focused (the case
// this whole feature exists for). We send "data"-only messages from
// functions/index.ts (not "notification" payloads) so we control the tag
// (collapsing duplicates, same as lib/notifications.ts does) and attach a
// deep-link URL for notificationclick below.
messaging.onBackgroundMessage((payload) => {
  const data = payload.data || {};
  const title = data.title || 'Kojlux Study Hub';
  const body = data.body || 'You have something to review.';
  const tag = data.tag || 'kojlux-notification';
  const url = data.url || self.registration.scope;

  self.registration.showNotification(title, {
    body,
    tag,
    data: { url },
    icon: '/icon-192.png',
    badge: '/icon-192.png',
  });
});

// Tapping the notification focuses an already-open tab if there is one,
// otherwise opens a new one at the deep-linked URL.
self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const url = (event.notification.data && event.notification.data.url) || self.registration.scope;
  event.waitUntil(
    clients.matchAll({ type: 'window', includeUncontrolled: true }).then((windowClients) => {
      for (const client of windowClients) {
        if ('focus' in client) {
          client.navigate(new URL(url, self.registration.scope).href);
          return client.focus();
        }
      }
      if (clients.openWindow) return clients.openWindow(url);
    })
  );
});